#[derive(Debug, Clone, Copy, PartialEq)]
pub struct CalcLength {
    pub abs: Pt,
    pub percent: f32,
    pub em: f32,
    pub rem: f32,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ClampedLength {
    pub value: CalcLength,
    pub min: Option<Pt>,
    pub max: Option<Pt>,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FontRelativeLength {
    pub base: CalcLength,
    pub ex: f32,
    pub ch: f32,
    pub cap: f32,
    pub lh: f32,
    pub rlh: f32,
}

impl FontRelativeLength {
    pub fn resolve(self, avail: Pt, font_size: Pt, root_font_size: Pt) -> Pt {
        self.base.resolve(avail, font_size, root_font_size)
            + font_size * (self.ex * 0.5)
            + font_size * (self.ch * 0.5)
            + font_size * (self.cap * 0.7)
            + font_size * (self.lh * 1.2)
            + root_font_size * (self.rlh * 1.2)
    }
}

impl ClampedLength {
    pub fn resolve(self, avail: Pt, font_size: Pt, root_font_size: Pt) -> Pt {
        let mut value = self.value.resolve(avail, font_size, root_font_size);
        // CSS clamp ordering gives the minimum precedence when bounds are
        // inverted: max(MIN, min(VAL, MAX)). Applying the upper bound first
        // preserves that behavior and also represents nested min()/max().
        if let Some(maximum) = self.max {
            value = value.min(maximum);
        }
        if let Some(minimum) = self.min {
            value = value.max(minimum);
        }
        value
    }
}

impl CalcLength {
    pub fn zero() -> Self {
        Self {
            abs: Pt::ZERO,
            percent: 0.0,
            em: 0.0,
            rem: 0.0,
        }
    }

    pub fn resolve(self, avail: Pt, font_size: Pt, root_font_size: Pt) -> Pt {
        self.abs + (avail * self.percent) + (font_size * self.em) + (root_font_size * self.rem)
    }
}

impl LengthSpec {
    fn resolve_inline_percentage_component(
        self,
        percentage_basis: Pt,
        font_size: Pt,
        root_font_size: Pt,
    ) -> Self {
        let has_percentage = match self {
            LengthSpec::Percent(value) => value.abs() > f32::EPSILON,
            LengthSpec::Calc(value) => value.percent.abs() > f32::EPSILON,
            LengthSpec::Clamped(value) => value.value.percent.abs() > f32::EPSILON,
            LengthSpec::FontRelative(value) => value.base.percent.abs() > f32::EPSILON,
            _ => false,
        };
        if has_percentage {
            LengthSpec::Absolute(self.resolve_width(percentage_basis, font_size, root_font_size))
        } else {
            self
        }
    }

    pub(crate) fn resolve_width(self, avail_width: Pt, font_size: Pt, root_font_size: Pt) -> Pt {
        let value = match self {
            LengthSpec::Auto
            | LengthSpec::Content
            | LengthSpec::MinContent
            | LengthSpec::MaxContent
            | LengthSpec::FitContent => Pt::ZERO,
            LengthSpec::Absolute(value) => value,
            LengthSpec::Percent(value) => avail_width * value,
            LengthSpec::Em(value) => font_size * value,
            LengthSpec::Rem(value) => root_font_size * value,
            LengthSpec::Calc(calc) => calc.resolve(avail_width, font_size, root_font_size),
            LengthSpec::Clamped(calc) => calc.resolve(avail_width, font_size, root_font_size),
            LengthSpec::FontRelative(calc) => calc.resolve(avail_width, font_size, root_font_size),
            LengthSpec::Inherit | LengthSpec::Initial => Pt::ZERO,
        };
        value
    }

    pub(crate) fn resolve_height(self, avail_height: Pt, font_size: Pt, root_font_size: Pt) -> Pt {
        let value = match self {
            LengthSpec::Auto
            | LengthSpec::Content
            | LengthSpec::MinContent
            | LengthSpec::MaxContent
            | LengthSpec::FitContent => Pt::ZERO,
            LengthSpec::Absolute(value) => value,
            LengthSpec::Percent(value) => avail_height * value,
            LengthSpec::Em(value) => font_size * value,
            LengthSpec::Rem(value) => root_font_size * value,
            LengthSpec::Calc(calc) => calc.resolve(avail_height, font_size, root_font_size),
            LengthSpec::Clamped(calc) => calc.resolve(avail_height, font_size, root_font_size),
            LengthSpec::FontRelative(calc) => calc.resolve(avail_height, font_size, root_font_size),
            LengthSpec::Inherit | LengthSpec::Initial => Pt::ZERO,
        };
        value
    }
}

