#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FlexMargins {
    pub top: Option<Pt>,
    pub right: Option<Pt>,
    pub bottom: Option<Pt>,
    pub left: Option<Pt>,
}

impl FlexMargins {
    fn zero() -> Self {
        Self {
            top: Some(Pt::ZERO),
            right: Some(Pt::ZERO),
            bottom: Some(Pt::ZERO),
            left: Some(Pt::ZERO),
        }
    }
}

impl EdgeSizes {
    pub fn zero() -> Self {
        Self {
            top: LengthSpec::Absolute(Pt::ZERO),
            right: LengthSpec::Absolute(Pt::ZERO),
            bottom: LengthSpec::Absolute(Pt::ZERO),
            left: LengthSpec::Absolute(Pt::ZERO),
        }
    }

    fn resolve(self, avail_width: Pt, font_size: Pt, root_font_size: Pt) -> ResolvedEdges {
        ResolvedEdges {
            top: self
                .top
                .resolve_width(avail_width, font_size, root_font_size),
            right: self
                .right
                .resolve_width(avail_width, font_size, root_font_size),
            bottom: self
                .bottom
                .resolve_width(avail_width, font_size, root_font_size),
            left: self
                .left
                .resolve_width(avail_width, font_size, root_font_size),
        }
    }

    fn resolve_inline_percentage_components(
        self,
        percentage_basis: Pt,
        font_size: Pt,
        root_font_size: Pt,
    ) -> Self {
        Self {
            top: self.top.resolve_inline_percentage_component(
                percentage_basis,
                font_size,
                root_font_size,
            ),
            right: self.right.resolve_inline_percentage_component(
                percentage_basis,
                font_size,
                root_font_size,
            ),
            bottom: self.bottom.resolve_inline_percentage_component(
                percentage_basis,
                font_size,
                root_font_size,
            ),
            left: self.left.resolve_inline_percentage_component(
                percentage_basis,
                font_size,
                root_font_size,
            ),
        }
    }
}

