#[derive(Debug, Clone, PartialEq)]
pub struct PaintFilterSpec {
    pub saturate: f32,
    pub brightness: f32,
    pub contrast: f32,
    pub invert: f32,
    pub sepia: f32,
    pub hue_rotate: f32,
    pub opacity: f32,
    pub blur_radius: Pt,
    pub drop_shadows: Vec<FilterDropShadowSpec>,
    /// Authored-order filter bytecode. Aggregate fields above remain as a
    /// compact compatibility summary for native colour-only fast paths.
    pub operations: Vec<PaintFilterOperation>,
}

impl PaintFilterSpec {
    pub fn identity() -> Self {
        Self {
            saturate: 1.0,
            brightness: 1.0,
            contrast: 1.0,
            invert: 0.0,
            sepia: 0.0,
            hue_rotate: 0.0,
            opacity: 1.0,
            blur_radius: Pt::ZERO,
            drop_shadows: Vec::new(),
            operations: Vec::new(),
        }
    }

    pub fn is_identity(&self) -> bool {
        (self.saturate - 1.0).abs() <= 1.0e-6
            && (self.brightness - 1.0).abs() <= 1.0e-6
            && (self.contrast - 1.0).abs() <= 1.0e-6
            && self.invert.abs() <= 1.0e-6
            && self.sepia.abs() <= 1.0e-6
            && self.hue_rotate.abs() <= 1.0e-6
            && (self.opacity - 1.0).abs() <= 1.0e-6
            && self.blur_radius <= Pt::ZERO
            && self.drop_shadows.is_empty()
            && self.operations.is_empty()
    }
}

