impl AbsolutePositionedFlowable {
    pub fn new(
        child: Box<dyn Flowable>,
        left: LengthSpec,
        top: LengthSpec,
        right: LengthSpec,
        bottom: LengthSpec,
        width_spec: LengthSpec,
        height_spec: LengthSpec,
        z_index: i32,
        font_size: f32,
        root_font_size: f32,
    ) -> Self {
        Self::new_pt(
            child,
            left,
            top,
            right,
            bottom,
            width_spec,
            height_spec,
            z_index,
            Pt::from_f32(font_size),
            Pt::from_f32(root_font_size),
        )
    }

    pub fn new_pt(
        child: Box<dyn Flowable>,
        left: LengthSpec,
        top: LengthSpec,
        right: LengthSpec,
        bottom: LengthSpec,
        width_spec: LengthSpec,
        height_spec: LengthSpec,
        z_index: i32,
        font_size: Pt,
        root_font_size: Pt,
    ) -> Self {
        let child = if child.has_propagated_text_decoration() {
            child.without_propagated_text_decoration()
        } else {
            child
        };
        Self {
            child,
            css_terminal_baseline_rounded_child: None,
            left,
            top,
            right,
            bottom,
            width_spec,
            height_spec,
            z_index,
            font_size,
            root_font_size,
            pagination: Pagination::default(),
            fixed_positioned: false,
            explicit_grid_area_containing_block: false,
            fragment_block_end_relocated: false,
        }
    }

    pub fn with_pagination(mut self, pagination: Pagination) -> Self {
        self.pagination = pagination;
        self
    }

    pub fn with_fixed_positioned(mut self, fixed_positioned: bool) -> Self {
        self.fixed_positioned = fixed_positioned;
        self
    }

    pub(crate) fn with_explicit_grid_area_containing_block(mut self, enabled: bool) -> Self {
        self.explicit_grid_area_containing_block = enabled;
        self
    }

    pub(crate) fn with_css_terminal_baseline_rounding(mut self, enabled: bool) -> Self {
        self.css_terminal_baseline_rounded_child =
            enabled.then(|| self.child.with_css_terminal_baseline_rounding());
        self
    }
}

impl RelativePositionedFlowable {
    pub fn new_pt(
        child: Box<dyn Flowable>,
        left: LengthSpec,
        top: LengthSpec,
        right: LengthSpec,
        bottom: LengthSpec,
        font_size: Pt,
        root_font_size: Pt,
    ) -> Self {
        Self {
            child,
            left,
            top,
            right,
            bottom,
            z_index: 0,
            font_size,
            root_font_size,
            pagination: Pagination::default(),
        }
    }

    pub fn with_pagination(mut self, pagination: Pagination) -> Self {
        self.pagination = pagination;
        self
    }

    pub fn with_z_index(mut self, z_index: i32) -> Self {
        self.z_index = z_index;
        self
    }

    fn paint_offset(&self, avail_width: Pt, avail_height: Pt) -> (Pt, Pt) {
        let has_left = !matches!(self.left, LengthSpec::Auto);
        let has_right = !matches!(self.right, LengthSpec::Auto);
        let has_top = !matches!(self.top, LengthSpec::Auto);
        let has_bottom = !matches!(self.bottom, LengthSpec::Auto);
        let offset_width_basis = avail_width.max(Pt::ZERO);
        let offset_height_basis = avail_height.max(Pt::ZERO);
        let left = self
            .left
            .resolve_width(offset_width_basis, self.font_size, self.root_font_size);
        let right =
            self.right
                .resolve_width(offset_width_basis, self.font_size, self.root_font_size);
        let top = self
            .top
            .resolve_height(offset_height_basis, self.font_size, self.root_font_size);
        let bottom =
            self.bottom
                .resolve_height(offset_height_basis, self.font_size, self.root_font_size);
        let dx = if has_left {
            left
        } else if has_right {
            -right
        } else {
            Pt::ZERO
        };
        let dy = if has_top {
            top
        } else if has_bottom {
            -bottom
        } else {
            Pt::ZERO
        };
        (dx, dy)
    }
}

impl Flowable for AbsolutePositionedFlowable {
    fn wrap(&self, _avail_width: Pt, _avail_height: Pt) -> Size {
        Size {
            width: Pt::ZERO,
            height: Pt::ZERO,
        }
    }

    fn split(
        &self,
        _avail_width: Pt,
        _avail_height: Pt,
    ) -> Option<(Box<dyn Flowable>, Box<dyn Flowable>)> {
        None
    }

    fn draw(&self, canvas: &mut Canvas, x: Pt, y: Pt, _avail_width: Pt, _avail_height: Pt) {
        let (containing_x, containing_y, containing_width, containing_height) =
            if !self.fixed_positioned {
                canvas.current_abs_containing_block().map(|rect| {
                    (
                        rect.x,
                        rect.y,
                        rect.width.max(Pt::ZERO),
                        rect.height.max(Pt::ZERO),
                    )
                })
            } else {
                None
            }
            .unwrap_or_else(|| {
                let page = canvas.page_size();
                (
                    Pt::ZERO,
                    Pt::ZERO,
                    page.width.max(Pt::ZERO),
                    page.height.max(Pt::ZERO),
                )
            });
        let draw_child = self
            .css_terminal_baseline_rounded_child
            .as_deref()
            .filter(|_| containing_y.to_milli_i64().rem_euclid(750) == 0)
            .unwrap_or(self.child.as_ref());
        let has_left = !matches!(self.left, LengthSpec::Auto);
        let has_right = !matches!(self.right, LengthSpec::Auto);
        let has_top = !matches!(self.top, LengthSpec::Auto);
        let has_bottom = !matches!(self.bottom, LengthSpec::Auto);

        let left = if has_left {
            self.left
                .resolve_width(containing_width, self.font_size, self.root_font_size)
        } else {
            Pt::ZERO
        };
        let right = if has_right {
            self.right
                .resolve_width(containing_width, self.font_size, self.root_font_size)
        } else {
            Pt::ZERO
        };
        let top = if has_top {
            self.top
                .resolve_height(containing_height, self.font_size, self.root_font_size)
        } else {
            Pt::ZERO
        };
        let bottom = if has_bottom {
            self.bottom
                .resolve_height(containing_height, self.font_size, self.root_font_size)
        } else {
            Pt::ZERO
        };
        let left = left;
        let right = right;
        let top = top;
        let bottom = bottom;

        // CSS-ish positioning behavior:
        // - If both sides are set and size is auto, stretch to fill.
        // - If both sides are set and size is explicit, keep explicit size
        //   and anchor from the start side (left/top in current LTR model).
        // - If only one side is set, anchor there and use the child's intrinsic size.
        // - If neither is set, default to 0.
        let width_auto = matches!(self.width_spec, LengthSpec::Auto);
        let height_auto = matches!(self.height_spec, LengthSpec::Auto);
        let stretch_w = has_left && has_right && width_auto;
        let stretch_h = has_top && has_bottom && height_auto;

        let explicit_w = if width_auto {
            None
        } else {
            Some(
                self.width_spec
                    .resolve_width(containing_width, self.font_size, self.root_font_size)
                    .max(Pt::ZERO),
            )
        };
        let explicit_h = if height_auto {
            None
        } else {
            Some(
                self.height_spec
                    .resolve_height(containing_height, self.font_size, self.root_font_size)
                    .max(Pt::ZERO),
            )
        };

        let avail_w_for_child = if let Some(explicit_w) = explicit_w {
            explicit_w.max(Pt::ZERO)
        } else if stretch_w {
            (containing_width - left - right).max(Pt::ZERO)
        } else if has_left {
            (containing_width - left).max(Pt::ZERO)
        } else if has_right {
            (containing_width - right).max(Pt::ZERO)
        } else {
            containing_width
        };
        let avail_h_for_child = if let Some(explicit_h) = explicit_h {
            explicit_h.max(Pt::ZERO)
        } else if stretch_h {
            (containing_height - top - bottom).max(Pt::ZERO)
        } else if has_top {
            (containing_height - top).max(Pt::ZERO)
        } else if has_bottom {
            (containing_height - bottom).max(Pt::ZERO)
        } else {
            containing_height
        };

        // Shrink-to-fit for absolutely positioned elements when width is auto.
        // Prefer intrinsic width when available, clamped to the available space.
        let target_w = if let Some(explicit_w) = explicit_w {
            explicit_w.max(Pt::ZERO)
        } else if stretch_w {
            avail_w_for_child
        } else if let Some(intrinsic) = self.child.intrinsic_width() {
            intrinsic.min(avail_w_for_child).max(Pt::ZERO)
        } else {
            avail_w_for_child
        };

        let size = self.child.wrap(target_w, avail_h_for_child);

        let child_w = if let Some(explicit_w) = explicit_w {
            explicit_w.max(Pt::ZERO)
        } else if stretch_w {
            avail_w_for_child
        } else {
            size.width.min(target_w).max(Pt::ZERO)
        };
        let child_h = if let Some(explicit_h) = explicit_h {
            explicit_h.max(Pt::ZERO)
        } else if stretch_h {
            avail_h_for_child
        } else {
            size.height.min(avail_h_for_child).max(Pt::ZERO)
        };

        let child_x = if has_left {
            containing_x + left
        } else if has_right {
            containing_x + (containing_width - right - child_w)
        } else {
            x
        };
        let fragment_inline_half_leading = if self.fragment_block_end_relocated && height_auto {
            self.child
                .fragment_block_end_inline_leading(target_w)
                .unwrap_or(Pt::ZERO)
                .min(child_h)
                .max(Pt::ZERO)
                .mul_ratio(1, 2)
        } else {
            Pt::ZERO
        };
        let child_y = if has_top {
            containing_y + top
        } else if has_bottom {
            // Relocation changes which containing-block fragment owns the
            // absolute box. CSS distributes a single line's leading equally
            // above and below its em box, so only its block-end half is visual
            // overflow at the terminal-fragment anchor.
            containing_y + (containing_height - bottom - child_h) + fragment_inline_half_leading
        } else {
            y
        };

        if stretch_h {
            draw_child.draw_stretched(canvas, child_x, child_y, child_w, child_h);
        } else {
            draw_child.draw(canvas, child_x, child_y, child_w, child_h);
        }
    }

    fn out_of_flow_static_size(&self, avail_width: Pt, avail_height: Pt) -> Option<Size> {
        let width = if matches!(self.width_spec, LengthSpec::Auto) {
            self.child
                .intrinsic_width()
                .unwrap_or_else(|| self.child.wrap(avail_width, avail_height).width)
                .min(avail_width)
                .max(Pt::ZERO)
        } else {
            self.width_spec
                .resolve_width(avail_width, self.font_size, self.root_font_size)
                .max(Pt::ZERO)
        };
        let height = if matches!(self.height_spec, LengthSpec::Auto) {
            self.child.wrap(width, avail_height).height.max(Pt::ZERO)
        } else {
            self.height_spec
                .resolve_height(avail_height, self.font_size, self.root_font_size)
                .max(Pt::ZERO)
        };
        Some(Size { width, height })
    }

    fn out_of_flow(&self) -> bool {
        true
    }

    fn uses_explicit_grid_area_containing_block(&self) -> bool {
        self.explicit_grid_area_containing_block
    }

    fn positions_from_fragment_block_end(&self) -> bool {
        !self.fixed_positioned
            && matches!(self.top, LengthSpec::Auto)
            && !matches!(self.bottom, LengthSpec::Auto)
    }

    fn extract_fragment_block_end_positioned(
        &self,
    ) -> (Option<Box<dyn Flowable>>, Vec<Box<dyn Flowable>>) {
        if self.positions_from_fragment_block_end() {
            let mut relocated = self.clone();
            relocated.fragment_block_end_relocated = true;
            (None, vec![Box::new(relocated) as Box<dyn Flowable>])
        } else {
            (Some(Box::new(self.clone())), Vec::new())
        }
    }

    fn is_positioned(&self) -> bool {
        true
    }

    fn z_index(&self) -> i32 {
        self.z_index
    }

    fn pagination(&self) -> Pagination {
        self.pagination
    }

    fn is_fixed_positioned(&self) -> bool {
        self.fixed_positioned
    }
}

