            ContainerFlowable::new_pt(vec![Box::new(item)], Pt::from_f32(12.0), Pt::from_f32(12.0));

        let (first, second) = parent
            .split(Pt::from_f32(120.0), Pt::from_f32(102.0))
            .expect("the sub-point painted tail must survive fragmentation");

