    #[test]
    fn definite_height_grid_does_not_apply_inline_top_overflow_twice() {
        let drawn_y = Arc::new(Mutex::new(Vec::new()));
        let line = CssLineBoxFlowable::new(Box::new(GridBaselineOverflowProbe {
            size: Size {
                width: Pt::from_f32(80.0),
                height: Pt::from_f32(36.0),
            },
            baseline: Pt::from_f32(30.0),
            inline_ascent: Pt::from_f32(30.75),
            drawn_y: drawn_y.clone(),
        }));
        let item =
            ContainerFlowable::new_pt(vec![Box::new(line)], Pt::from_f32(12.0), Pt::from_f32(12.0));
        let auto_height = FlexFlowable::new_pt(
            vec![(Box::new(item), 0.0, 1.0, None, None)],
            FlexDirection::Row,
            JustifyContent::FlexStart,
            AlignItems::Stretch,
            AlignContent::Stretch,
            LengthSpec::Absolute(Pt::ZERO),
            true,
            Pt::from_f32(12.0),
            Pt::from_f32(12.0),
        )
        .with_grid_tracks(1, vec![GridTrackSize::auto()]);
        assert!(auto_height.grid_items_round_baselines());

        let definite_height = auto_height.with_grid_definite_height(true);
        assert!(!definite_height.grid_items_round_baselines());
        let page = Size {
            width: Pt::from_f32(100.0),
            height: Pt::from_f32(64.0),
        };
        let mut canvas = Canvas::new(page);
        definite_height.draw(&mut canvas, Pt::ZERO, Pt::ZERO, page.width, page.height);

        assert_eq!(
            *drawn_y.lock().expect("grid baseline draw positions"),
            vec![Pt::ZERO]
        );
    }

    #[test]
    fn column_wrap_forms_columns_with_independent_axis_gaps() {
        let item_width = Pt::from_f32(52.5);
        let item_height = Pt::from_f32(45.0);
        let items = (0..4)
            .map(|_| {
                (
                    Box::new(
                        ContainerFlowable::new_pt(
                            Vec::new(),
                            Pt::from_f32(12.0),
                            Pt::from_f32(12.0),
                        )
                        .with_width(LengthSpec::Absolute(item_width))
                        .with_height(LengthSpec::Absolute(item_height)),
                    ) as Box<dyn Flowable>,
                    0.0,
                    1.0,
                    Some(LengthSpec::Absolute(item_height)),
                    None,
                )
            })
            .collect();
        let flex = FlexFlowable::new_pt(
            items,
            FlexDirection::Column,
            JustifyContent::FlexStart,
            AlignItems::FlexStart,
            AlignContent::FlexStart,
            LengthSpec::Absolute(Pt::ZERO),
            true,
            Pt::from_f32(12.0),
            Pt::from_f32(12.0),
        )
        .with_axis_gaps(
            LengthSpec::Absolute(Pt::from_f32(7.5)),
            LengthSpec::Absolute(Pt::from_f32(10.5)),
        );

        let layout = flex.compute_layout(Pt::from_f32(177.0), Pt::from_f32(109.5));
        let FlexLayout::ColumnWrap {
            columns,
            container_h,
        } = layout.layout
        else {
            panic!("expected wrapped flex columns");
        };
        assert_eq!(container_h, Pt::from_f32(109.5));
        assert_eq!(columns.len(), 2);
        assert_eq!(columns[0].indices, vec![0, 1]);
        assert_eq!(columns[1].indices, vec![2, 3]);
        assert_eq!(columns[0].column_w, item_width);
        assert_eq!(columns[1].column_w, item_width);
        assert_eq!(columns[0].sizes[0].height, item_height);
        assert_eq!(columns[0].sizes[1].height, item_height);
    }

