    #[test]
    fn forced_page_breaks_split_column_items_and_wrapped_row_lines() {
        let fixed_item = |width: f32, height: f32, pagination: Pagination| {
            Box::new(
                ContainerFlowable::new_pt(Vec::new(), Pt::from_f32(12.0), Pt::from_f32(12.0))
                    .with_width(LengthSpec::Absolute(Pt::from_f32(width)))
                    .with_height(LengthSpec::Absolute(Pt::from_f32(height)))
                    .with_pagination(pagination),
            ) as Box<dyn Flowable>
        };
        let column = FlexFlowable::new_pt(
            vec![
                (
                    fixed_item(
                        60.0,
                        45.0,
                        Pagination {
                            break_after: BreakAfter::Page,
                            ..Pagination::default()
                        },
                    ),
                    0.0,
                    1.0,
                    Some(LengthSpec::Absolute(Pt::from_f32(45.0))),
                    None,
                ),
                (
                    fixed_item(60.0, 45.0, Pagination::default()),
                    0.0,
                    1.0,
                    Some(LengthSpec::Absolute(Pt::from_f32(45.0))),
                    None,
                ),
            ],
            FlexDirection::Column,
            JustifyContent::FlexStart,
            AlignItems::FlexStart,
            AlignContent::FlexStart,
            LengthSpec::Absolute(Pt::ZERO),
            false,
            Pt::from_f32(12.0),
            Pt::from_f32(12.0),
        );
        assert!(
            column
                .split(Pt::from_f32(100.0), Pt::from_f32(100.0))
                .is_some(),
            "a forced break must split even when both items geometrically fit"
        );

        let row_item = |break_before| {
            (
                fixed_item(
                    60.0,
                    30.0,
                    Pagination {
                        break_before,
                        ..Pagination::default()
                    },
                ),
                0.0,
                0.0,
                Some(LengthSpec::Absolute(Pt::from_f32(60.0))),
                None,
            )
        };
        let wrapped_row = FlexFlowable::new_pt(
            vec![
                row_item(BreakBefore::Auto),
                row_item(BreakBefore::Auto),
                row_item(BreakBefore::Page),
                row_item(BreakBefore::Auto),
            ],
            FlexDirection::Row,
            JustifyContent::FlexStart,
            AlignItems::FlexStart,
            AlignContent::FlexStart,
            LengthSpec::Absolute(Pt::from_f32(10.0)),
            true,
            Pt::from_f32(12.0),
            Pt::from_f32(12.0),
        );
        assert!(
            wrapped_row
                .split(Pt::from_f32(130.0), Pt::from_f32(100.0))
                .is_some(),
            "a forced item break must propagate to its wrapped flex line"
        );
    }

    #[test]
    fn reversed_flex_axes_mirror_geometry_without_reversing_paint_order() {
        let explicit_height = MetaFlowable::new(
            Box::new(
                ContainerFlowable::new_pt(Vec::new(), Pt::from_f32(12.0), Pt::from_f32(12.0))
                    .with_height(LengthSpec::Absolute(Pt::from_f32(20.0))),
            ),
            Vec::new(),
        );
        let auto_height = MetaFlowable::new(
            Box::new(ContainerFlowable::new_pt(
                Vec::new(),
                Pt::from_f32(12.0),
                Pt::from_f32(12.0),
            )),
            Vec::new(),
        );
        assert!(!explicit_height.accepts_stretched_height());
        assert!(auto_height.accepts_stretched_height());

        let calls = Arc::new(Mutex::new(Vec::new()));
        let item = |id| {
            (
                Box::new(PositionProbe {
                    id,
                    height: Pt::from_f32(20.0),
                    calls: calls.clone(),
                }) as Box<dyn Flowable>,
                0.0,
                0.0,
                Some(LengthSpec::Absolute(Pt::from_f32(30.0))),
                None,
            )
        };
        let flex = FlexFlowable::new_pt(
            vec![item(1), item(2)],
            FlexDirection::Row,
            JustifyContent::FlexStart,
            AlignItems::FlexStart,
            AlignContent::FlexStart,
            LengthSpec::Absolute(Pt::ZERO),
            false,
            Pt::from_f32(12.0),
            Pt::from_f32(12.0),
        )
        .with_reversals(true, false);
        let layout = flex.compute_layout(Pt::from_f32(100.0), Pt::from_f32(40.0));
        let FlexLayout::RowNoWrap { widths, .. } = layout.layout else {
            panic!("expected one flex row");
        };
        assert_eq!(widths, vec![Pt::from_f32(30.0), Pt::from_f32(30.0)]);

        let mut canvas = Canvas::new(Size {
            width: Pt::from_f32(100.0),
            height: Pt::from_f32(40.0),
        });
        flex.draw(
            &mut canvas,
            Pt::ZERO,
            Pt::ZERO,
            Pt::from_f32(100.0),
            Pt::from_f32(40.0),
        );
        assert_eq!(
            *calls.lock().expect("position calls"),
            vec![
                (1, Pt::from_f32(70.0), Pt::ZERO),
                (2, Pt::from_f32(40.0), Pt::ZERO),
            ]
        );

        calls.lock().expect("position calls").clear();
        let column_item = |id| {
            (
                Box::new(PositionProbe {
                    id,
                    height: Pt::from_f32(20.0),
                    calls: calls.clone(),
                }) as Box<dyn Flowable>,
                0.0,
                0.0,
                Some(LengthSpec::Absolute(Pt::from_f32(30.0))),
                None,
            )
        };
        let column = FlexFlowable::new_pt(
            vec![column_item(1), column_item(2)],
            FlexDirection::Column,
            JustifyContent::FlexStart,
            AlignItems::FlexStart,
            AlignContent::FlexStart,
            LengthSpec::Absolute(Pt::ZERO),
            false,
            Pt::from_f32(12.0),
            Pt::from_f32(12.0),
        )
        .with_reversals(true, false);
        let mut canvas = Canvas::new(Size {
            width: Pt::from_f32(100.0),
            height: Pt::from_f32(100.0),
        });
        column.draw(
            &mut canvas,
            Pt::ZERO,
            Pt::ZERO,
            Pt::from_f32(100.0),
            Pt::from_f32(100.0),
        );
        assert_eq!(
            *calls.lock().expect("position calls"),
            vec![
                (1, Pt::ZERO, Pt::from_f32(70.0)),
                (2, Pt::ZERO, Pt::from_f32(40.0)),
            ]
        );

        calls.lock().expect("position calls").clear();
        let wrap_item = |id| {
            (
                Box::new(PositionProbe {
                    id,
                    height: Pt::from_f32(20.0),
                    calls: calls.clone(),
                }) as Box<dyn Flowable>,
                0.0,
                0.0,
                Some(LengthSpec::Absolute(Pt::from_f32(60.0))),
                None,
            )
        };
        let wrap_reverse = FlexFlowable::new_pt(
            vec![wrap_item(1), wrap_item(2)],
            FlexDirection::Row,
            JustifyContent::FlexStart,
            AlignItems::FlexStart,
            AlignContent::FlexStart,
            LengthSpec::Absolute(Pt::ZERO),
            true,
            Pt::from_f32(12.0),
            Pt::from_f32(12.0),
        )
        .with_reversals(false, true);
        let mut canvas = Canvas::new(Size {
            width: Pt::from_f32(100.0),
            height: Pt::from_f32(100.0),
        });
        wrap_reverse.draw(
            &mut canvas,
            Pt::ZERO,
            Pt::ZERO,
            Pt::from_f32(100.0),
            Pt::from_f32(100.0),
        );
        assert_eq!(
            *calls.lock().expect("position calls"),
            vec![
                (1, Pt::ZERO, Pt::from_f32(80.0)),
                (2, Pt::ZERO, Pt::from_f32(60.0)),
            ]
        );
    }

    #[test]
    fn overlapping_grid_layers_share_geometry_and_paint_in_z_index_order() {
        let order = Arc::new(Mutex::new(Vec::new()));
        let probe = |id| {
            Box::new(PaintOrderProbe {
                id,
                height: Pt::from_f32(20.0),
                out_of_flow: false,
                positioned: false,
                fixed_positioned: false,
                z_index: 0,
                order: order.clone(),
            }) as Box<dyn Flowable>
        };
        let overlay = OverlayFlowable::new(vec![(probe(1), 3), (probe(2), 1), (probe(3), 2)]);
        let available = Pt::from_f32(100.0);
        let mut canvas = Canvas::new(Size {
            width: available,
            height: available,
        });

        overlay.draw_stretched(&mut canvas, Pt::ZERO, Pt::ZERO, available, available);

        assert_eq!(*order.lock().expect("paint order"), vec![2, 3, 1]);
    }

    #[test]
    fn grid_overlay_uses_local_containing_block_only_for_explicit_absolute_area() {
        let calls = Arc::new(Mutex::new(Vec::new()));
        let absolute = |id, explicit_grid_area| {
            Box::new(
                AbsolutePositionedFlowable::new_pt(
                    Box::new(PositionProbe {
                        id,
                        height: Pt::from_f32(20.0),
                        calls: calls.clone(),
                    }),
                    LengthSpec::Absolute(Pt::from_f32(10.0)),
                    LengthSpec::Absolute(Pt::from_f32(10.0)),
                    LengthSpec::Auto,
                    LengthSpec::Auto,
                    LengthSpec::Absolute(Pt::from_f32(20.0)),
                    LengthSpec::Absolute(Pt::from_f32(20.0)),
                    0,
                    Pt::from_f32(12.0),
                    Pt::from_f32(12.0),
                )
                .with_explicit_grid_area_containing_block(explicit_grid_area),
            ) as Box<dyn Flowable>
        };
        let auto_area = OverlayFlowable::new(vec![(absolute(1, false), 0)]);
        let explicit_area = OverlayFlowable::new(vec![(absolute(2, true), 0)]);
        let page = Size {
            width: Pt::from_f32(200.0),
            height: Pt::from_f32(120.0),
        };
        let mut canvas = Canvas::new(page);
        canvas.push_abs_containing_block(Rect {
            x: Pt::from_f32(5.0),
            y: Pt::from_f32(7.0),
            width: Pt::from_f32(100.0),
            height: Pt::from_f32(100.0),
        });

        auto_area.draw(
            &mut canvas,
            Pt::from_f32(30.0),
            Pt::from_f32(40.0),
            Pt::from_f32(50.0),
            Pt::from_f32(60.0),
        );
        explicit_area.draw(
            &mut canvas,
            Pt::from_f32(30.0),
            Pt::from_f32(40.0),
            Pt::from_f32(50.0),
            Pt::from_f32(60.0),
        );
        canvas.pop_abs_containing_block();

        assert_eq!(
            *calls.lock().expect("position calls"),
            vec![
                (1, Pt::from_f32(15.0), Pt::from_f32(17.0)),
                (2, Pt::from_f32(40.0), Pt::from_f32(50.0)),
            ]
        );
    }

    #[test]
    fn css_rotation_keeps_its_top_down_clockwise_sign_around_the_default_center() {
        let box_width = Pt::from_f32(75.0);
        let box_height = Pt::from_f32(45.0);
        let flowable =
            ContainerFlowable::new_pt(Vec::new(), Pt::from_f32(12.0), Pt::from_f32(12.0))
                .with_width(LengthSpec::Absolute(box_width))
                .with_height(LengthSpec::Absolute(box_height))
                .with_transforms(vec![CssTransformOp::Rotate { radians: 0.5 }]);
        let mut canvas = Canvas::new(Size {
            width: Pt::from_f32(200.0),
            height: Pt::from_f32(200.0),
        });
        flowable.draw(
            &mut canvas,
            Pt::ZERO,
            Pt::ZERO,
            Pt::from_f32(200.0),
            Pt::from_f32(200.0),
        );
        let document = canvas.finish();
        let commands = &document.pages[0].commands;
        let transform = commands.windows(3).find(|window| {
            matches!(
                window,
                [
                    Command::CssTransformOrigin { inverse: false, .. },
                    Command::Rotate(_),
                    Command::CssTransformOrigin { inverse: true, .. }
                ]
            )
        });
        let Some(
            [
                Command::CssTransformOrigin {
                    x: origin_x,
                    y: origin_y,
                    inverse: false,
                },
                Command::Rotate(angle),
                Command::CssTransformOrigin {
                    x: return_x,
                    y: return_y,
                    inverse: true,
                },
            ],
        ) = transform
        else {
            panic!("missing transform-origin command sequence: {commands:?}");
        };
        assert_eq!(*origin_x, box_width.mul_ratio(1, 2));
        assert_eq!(*origin_y, box_height.mul_ratio(1, 2));
        assert!((*angle - 0.5).abs() < f32::EPSILON);
        assert_eq!(*return_x, *origin_x);
        assert_eq!(*return_y, *origin_y);
    }

    #[test]
    fn filter_compiler_hoists_transform_out_of_reusable_source_tile() {
        let box_width = Pt::from_f32(75.0);
        let box_height = Pt::from_f32(45.0);
        let mut filter = PaintFilterSpec::identity();
        filter
            .operations
            .push(PaintFilterOperation::Brightness(0.8));
        let flowable =
            ContainerFlowable::new_pt(Vec::new(), Pt::from_f32(12.0), Pt::from_f32(12.0))
                .with_width(LengthSpec::Absolute(box_width))
                .with_height(LengthSpec::Absolute(box_height))
                .with_background(Some(Color::BLACK))
                .with_paint_filter(Some(filter))
                .with_transforms(vec![CssTransformOp::Rotate { radians: 0.5 }]);
        let mut canvas = Canvas::new(Size {
            width: Pt::from_f32(200.0),
            height: Pt::from_f32(200.0),
        });
        flowable.draw(
            &mut canvas,
            Pt::ZERO,
            Pt::ZERO,
            Pt::from_f32(200.0),
            Pt::from_f32(200.0),
        );
        let document = canvas.finish();
        let commands = &document.pages[0].commands;
        let (source_width, source_height, source_commands) = commands
            .iter()
            .find_map(|command| match command {
                Command::DefineForm {
                    width,
                    height,
                    commands,
                    ..
                } => Some((*width, *height, commands)),
                _ => None,
            })
            .expect("compiled filter source form");
        assert_eq!((source_width, source_height), (box_width, box_height));
        assert!(
            !source_commands.iter().any(|command| matches!(
                command,
                Command::CssTransformOrigin { .. }
                    | Command::Translate(..)
                    | Command::Scale(..)
                    | Command::Rotate(..)
                    | Command::ConcatMatrix { .. }
            )),
            "the cached filter source must remain in local coordinates"
        );

        let begin = commands
            .iter()
            .position(|command| matches!(command, Command::SaveState))
            .expect("transform state");
        let draw = commands
            .iter()
            .position(|command| matches!(command, Command::DrawFilteredForm { .. }))
            .expect("filtered tile draw");
        let end = commands
            .iter()
            .rposition(|command| matches!(command, Command::RestoreState))
            .expect("transform restore");
        assert!(begin < draw && draw < end);
        assert!(commands[begin..draw]
            .iter()
            .any(|command| matches!(command, Command::Rotate(angle) if (*angle - 0.5).abs() < f32::EPSILON)));
    }

    #[test]
    fn filter_composite_consumes_fragmentainer_clip_without_clipping_its_source() {
        let mut filter = PaintFilterSpec::identity();
        filter
            .operations
            .push(PaintFilterOperation::Brightness(0.8));
        let flowable =
            ContainerFlowable::new_pt(Vec::new(), Pt::from_f32(12.0), Pt::from_f32(12.0))
                .with_width(LengthSpec::Absolute(Pt::from_f32(80.0)))
                .with_height(LengthSpec::Absolute(Pt::from_f32(40.0)))
                .with_background(Some(Color::BLACK))
                .with_paint_filter(Some(filter));
        let mut canvas = Canvas::new(Size {
            width: Pt::from_f32(200.0),
            height: Pt::from_f32(200.0),
        });
        let fragmentainer = Rect {
            x: Pt::from_f32(10.0),
            y: Pt::from_f32(20.0),
            width: Pt::from_f32(90.0),
            height: Pt::from_f32(100.0),
        };
        canvas.push_fragmentainer(fragmentainer);
        flowable.draw(
            &mut canvas,
            Pt::from_f32(10.0),
            Pt::from_f32(20.0),
            Pt::from_f32(90.0),
            Pt::from_f32(100.0),
        );
        canvas.pop_fragmentainer();
        let document = canvas.finish();
        let commands = &document.pages[0].commands;
        let draw = commands
            .iter()
            .position(|command| matches!(command, Command::DrawFilteredForm { .. }))
            .expect("filtered composite");
        assert!(matches!(commands[draw - 2], Command::SaveState));
        assert!(matches!(
            commands[draw - 1],
            Command::ClipRect {
                x,
                y,
                width,
                height,
            } if x == fragmentainer.x
                && y == fragmentainer.y
                && width == fragmentainer.width
                && height == fragmentainer.height
        ));
        assert!(matches!(commands[draw + 1], Command::RestoreState));
        let source_commands = commands.iter().find_map(|command| match command {
            Command::DefineForm { commands, .. } => Some(commands),
            _ => None,
        });
        assert!(source_commands.is_some_and(|commands| {
            !commands
                .iter()
                .any(|command| matches!(command, Command::ClipRect { .. }))
        }));
    }

    #[test]
    fn filter_tile_outsets_retain_fractional_shadow_sampling_guard() {
        let shadow = FilterDropShadowSpec {
            offset_x: Pt::from_f32(1.5),
            offset_y: Pt::from_f32(0.75),
            blur_radius: Pt::ZERO,
            color: Color::BLACK,
            opacity: 1.0,
            color_is_current_color: false,
        };
        let mut filter = PaintFilterSpec::identity();
        filter.operations = vec![
            PaintFilterOperation::Contrast(1.08),
            PaintFilterOperation::DropShadow(shadow),
        ];

        let outsets = ContainerFlowable::compiled_css_filter_outsets(&filter)
            .expect("native CSS filter outsets");
        assert_eq!(outsets.top, Pt::ZERO);
        assert_eq!(outsets.left, Pt::ZERO);
        assert_eq!(outsets.right, Pt::from_f32(1.74));
        assert_eq!(outsets.bottom, Pt::from_f32(0.99));
    }

